// Independent protocol implementation; reference: keiyoushi/extensions-source (Apache-2.0),
// commit dbf6c05d6a9520c60533f1626616263522bbe71a, Guazimanhua.kt.
// Only public HTML data is parsed. No downloaded JavaScript is executed.
var BASE = 'https://www.guazimanhua.com';
var endPages = {};
function fail(message) { throw new Error('瓜子漫画：' + message); }
function publicUrl(url, kind) {
  var match = new RegExp('^https://www\\.guazimanhua\\.com/' + kind + '\\.php\\?id=([0-9]+)$').exec(url || '');
  if (!match) fail('无效的' + kind + '地址');
  return match[1];
}
async function html(url) {
  var response = await triomi.fetch(url);
  if (response.status !== 200) fail('网站 HTTP ' + response.status);
  var text = response.body || '';
  if (/cf-chl-|challenge-platform|Just a moment|Attention Required|人机验证|验证码/.test(text)) fail('网站要求验证，无法直接读取');
  return text;
}
async function value(body, selector, attr) {
  var rows = await triomi.select(body, selector, {v:{selector:'.',attr:attr || 'text'}});
  return rows.length ? String(rows[0].v || '').trim() : '';
}
async function listing(url, page, key) {
  page = Number(page) || 1;
  if (page < 1 || Math.floor(page) !== page) fail('页码无效');
  if (endPages[key] && page > endPages[key]) return [];
  var body = await html(url);
  var current = await value(body, 'nav.pager a.on');
  if (current && Number(current) < page) return [];
  var links = await triomi.select(body, 'nav.pager a', {text:{selector:'.'}});
  if (!links.some(function(link) {return link.text === '>';})) endPages[key] = page;
  var rows = await triomi.select(body, 'article.card', {
    title: 'h3 a',
    url: {selector:'a.cover-wrap',attr:'href',absolute:true},
    coverUrl: {selector:'img.cover',attr:'src',absolute:true},
    author: 'div.meta'
  }, url);
  if (!rows.length && !/暂无|没有找到|未找到|没有相关|无搜索结果/.test(body)) fail('无法识别漫画列表');
  var seen = {}, items = [];
  for (var i = 0; i < rows.length; i++) {
    var row = rows[i], id = publicUrl(row.url, 'comic');
    if (!row.title) fail('漫画标题缺失');
    if (seen[id]) continue;
    seen[id] = true;
    items.push({remoteId:id,title:row.title,url:row.url,coverUrl:row.coverUrl,author:(row.author || '').split(' · ')[0]});
  }
  return items;
}
async function discover(url, page) {
  if (!/^https:\/\/www\.guazimanhua\.com\/category\.php\?sort=(hits|update)&page=[0-9]+$/.test(url)) fail('无效的浏览地址');
  return listing(url, page, url.replace(/&page=[0-9]+$/, ''));
}
async function search(keyword, page) {
  page = Number(page) || 1;
  var key = BASE + '/category.php?keyword=' + encodeURIComponent(keyword) + '&sort=hits';
  return listing(key + '&page=' + page, page, key);
}
async function detail(url, snapshot) {
  var id = publicUrl(url, 'comic'), body = await html(url);
  var title = await value(body, 'div.mobile-comic-title');
  if (!title) fail('无法识别漫画详情');
  var authors = await triomi.select(body, 'div.cinema-strip > div', {label:'span',text:'b'});
  var author = '';
  for (var a = 0; a < authors.length; a++) if (authors[a].label === '作者') author = authors[a].text || '';
  var meta = await value(body, 'p.mobile-comic-meta');
  var tags = (await value(body, 'p.mobile-comic-tags')).split(/\s*[/·]\s*/).filter(function(t) {return !!t;});
  var raw = await triomi.select(body, 'section.mobile-comic-all-chapters div.mobile-chapter-grid a', {
    title:{selector:'.'},url:{selector:'.',attr:'href',absolute:true}
  }, url);
  if (!raw.length) fail('章节目录缺失');
  // The public detail page emits newest-first; reversing preserves announcements and extras.
  var chapters = [], seen = {};
  for (var i = raw.length - 1; i >= 0; i--) {
    var row = raw[i], chapterId = publicUrl(row.url, 'chapter');
    if (!row.title) fail('章节标题缺失');
    if (seen[chapterId]) continue;
    seen[chapterId] = true;
    chapters.push({remoteId:chapterId,title:row.title,url:row.url,volumeTitle:'章节',locked:false});
  }
  return {item:{remoteId:id,title:title,url:url,coverUrl:await value(body,'img.mobile-comic-cover','src'),
    author:author,description:await value(body,'p.mobile-comic-desc'),tags:tags,
    status:/完结|完結/.test(meta)?'completed':(/连载|連載/.test(meta)?'ongoing':'unknown')},chapters:chapters};
}
async function content(url, chapter) {
  publicUrl(url, 'chapter');
  var body = await html(url);
  var rows = await triomi.select(body, 'section.reader-images img', {url:{selector:'.',attr:'src',absolute:true}}, url);
  if (!rows.length) fail('章节未提供公开图片；可能已下架、要求登录或仅限官方应用');
  var images = [];
  for (var i = 0; i < rows.length; i++) {
    if (!/^https?:\/\//.test(rows[i].url || '')) fail('章节图片地址无效');
    images.push(rows[i].url);
  }
  return {images:images};
}
